from pathlib import Path

root = Path('/mnt/data/heavy_load_check')

# ---------------- backend/main.py ----------------
p = root/'webapp/backend/main.py'
s = p.read_text(encoding='utf-8')
s = s.replace('import time\n', 'import time\nimport threading\n')
old = 'RUN_HANDLES: dict[str, Any] = {}\n\n\ndef _read_json'
new = '''RUN_HANDLES: dict[str, Any] = {}\n\n# Short-lived snapshot cache: the UI polls several read-only endpoints at once.\n# Without this cache every request re-scans all platform SQLite DBs, resume metadata\n# and filesystem state, which makes the dashboard feel like it is constantly loading.\n_APP_SNAPSHOT_LOCK = threading.Lock()\n_APP_SNAPSHOT_CACHE: list[dict[str, Any]] | None = None\n_APP_SNAPSHOT_AT = 0.0\n_APP_SNAPSHOT_TTL = 2.5\n\n\ndef _read_json'''
if old not in s:
    raise SystemExit('backend insertion anchor missing')
s = s.replace(old, new, 1)

# Replace _all_applications with cached + indexed implementation.
start = s.index('def _all_applications() -> list[dict[str, Any]]:')
end = s.index('\n\ndef _resume_records()', start)
new_func = '''def _all_applications() -> list[dict[str, Any]]:\n    global _APP_SNAPSHOT_CACHE, _APP_SNAPSHOT_AT\n    now = time.monotonic()\n    if _APP_SNAPSHOT_CACHE is not None and (now - _APP_SNAPSHOT_AT) < _APP_SNAPSHOT_TTL:\n        return [dict(row) for row in _APP_SNAPSHOT_CACHE]\n\n    with _APP_SNAPSHOT_LOCK:\n        now = time.monotonic()\n        if _APP_SNAPSHOT_CACHE is not None and (now - _APP_SNAPSHOT_AT) < _APP_SNAPSHOT_TTL:\n            return [dict(row) for row in _APP_SNAPSHOT_CACHE]\n\n        result: list[dict[str, Any]] = []\n        meta = _metadata_by_url()\n\n        # Build the resume availability index once per snapshot. The old code called\n        # _resume_pdf_path_for_url() for every application, which recursively scanned\n        # resume_versions for every row (O(applications * resume_records)).\n        resume_index: set[tuple[str, ...]] = set()\n        try:\n            for r in _resume_records():\n                raw_pdf = _safe(r.get("pdf"))\n                pdf = Path(raw_pdf) if raw_pdf else Path(_safe(r.get("dir"))) / "resume.pdf"\n                if not pdf.is_absolute():\n                    pdf = ROOT / pdf\n                try:\n                    if not pdf.is_file() or pdf.suffix.lower() != ".pdf":\n                        continue\n                    url = _normalize_job_url(r.get("job_url"))\n                    key = _safe(r.get("job_key"))\n                    platform = _safe(r.get("platform")).lower()\n                    company = _safe_norm(r.get("company") or "")\n                    role = _normalize_resume_role(r.get("role") or "", platform)\n                    if url:\n                        resume_index.add(("url", url))\n                    if key and platform:\n                        resume_index.add(("key", platform, key))\n                    if key:\n                        resume_index.add(("key_any", key))\n                    if company and role:\n                        resume_index.add(("identity", platform, company, role))\n                except OSError:\n                    continue\n        except Exception:\n            resume_index = set()\n\n        for platform, path in _dbs():\n            try:\n                _ensure_application_columns(path)\n                con = _connect(path)\n                cols = {r[1] for r in con.execute("PRAGMA table_info(applications)").fetchall()}\n                selected = ["id", "job_url", "job_key", "title", "status", "created_at"]\n                for extra in ("company", "location", "description", "match_score", "eligible", "matched_skills"):\n                    if extra in cols:\n                        selected.append(extra)\n                rows = con.execute(f"SELECT {', '.join(selected)} FROM applications ORDER BY id DESC").fetchall()\n                con.close()\n            except sqlite3.Error:\n                continue\n\n            for r in rows:\n                row = dict(r)\n                m = meta.get(_safe(row.get("job_url")), {})\n                recovered = _recover_log_metadata(_safe(row.get("job_url")), platform) if not row.get("company") else {}\n                company = _safe(row.get("company")) or _safe(m.get("company")) or _safe(recovered.get("company"))\n                if not company and platform == "naukri":\n                    company = _infer_naukri_company(_safe(row.get("title")), _safe(row.get("job_url")))\n                title = _safe(row.get("title"))\n                if not title or title.startswith(("http://", "https://")):\n                    title = _safe(row.get("role")) or _safe(m.get("role")) or _safe(recovered.get("role")) or "Unknown role"\n                status_value = _safe(row.get("status")).lower()\n                external_statuses = {\n                    "external", "external_filled", "external_submitted", "external_partial",\n                    "external_error", "external_blocked", "external_apply_failed",\n                    "external_apply_click_failed", "external_apply_not_found",\n                    "external_apply_not_reached", "external_skipped",\n                }\n                native_statuses = {\n                    "apply_clicked", "applying", "application_ready", "awaiting_approval",\n                    "ready_for_manual_submit", "ready_to_submit", "submitted", "confirmed",\n                    "applied", "blocked", "human_intervention", "unknown_question",\n                    "no_questions", "answer_not_verified", "resume_upload_failed",\n                    "submission_unconfirmed", "submit_not_found", "naukri_apply_error",\n                    "application_error", "apply_click_failed", "apply_not_found",\n                    "match_found_no_direct_apply",\n                }\n                if status_value in external_statuses or status_value.startswith("external_"):\n                    application_route = "external"\n                elif status_value in native_statuses:\n                    application_route = "native"\n                else:\n                    application_route = "unknown"\n\n                normalized_url = _normalize_job_url(_safe(row.get("job_url")))\n                key = _safe(row.get("job_key"))\n                platform_l = _safe(platform).lower()\n                company_norm = _safe_norm(company or "")\n                role_norm = _normalize_resume_role(title or "", platform_l)\n                resume_available = bool(\n                    (normalized_url and ("url", normalized_url) in resume_index)\n                    or (key and ("key", platform_l, key) in resume_index)\n                    or (key and ("key_any", key) in resume_index)\n                    or (company_norm and role_norm and ("identity", platform_l, company_norm, role_norm) in resume_index)\n                )\n\n                row.update({\n                    "platform": platform,\n                    "candidate_id": _safe(_profile().get("contact", {}).get("email")) or "default",\n                    "db_id": row.get("id"),\n                    "job_ref": _web_job_ref(platform, row.get("id")),\n                    "job_id": row.get("id"),\n                    "company": company or "Unknown_Company",\n                    "title": title,\n                    "location": _safe(row.get("location")),\n                    "description": _safe(row.get("description")),\n                    "url": row.get("job_url") or "",\n                    "source": platform,\n                    "resume_version_id": None,\n                    "resume_pdf_available": resume_available,\n                    "submitted_at": row.get("created_at") if row.get("status") in {"submitted", "confirmed", "applied"} else None,\n                    "last_error": None,\n                    "updated_at": row.get("created_at"),\n                    "match_score": row.get("match_score"),\n                    "eligible": row.get("eligible"),\n                    "matched_skills": [x.strip() for x in _safe(row.get("matched_skills")).split(",") if x.strip()],\n                    "application_route": application_route,\n                })\n                result.append(row)\n\n        result.sort(key=lambda x: x.get("created_at") or "", reverse=True)\n        _APP_SNAPSHOT_CACHE = [dict(row) for row in result]\n        _APP_SNAPSHOT_AT = time.monotonic()\n        return [dict(row) for row in result]\n'''
s = s[:start] + new_func + s[end:]

# Dashboard response: include data already loaded, so Dashboard doesn't need 2 more heavy calls.
old_block = '''        "applications": {"total": len(apps), "submitted": submitted, "by_status": {}, "by_portal": [], "funnel": []},\n        "outreach": {"drafts": 0, "approved_unsent": 0, "sent": 0, "replied": 0, "response_rate": 0, "positive": 0, "negative": 0, "action_required": 0, "send_failed": 0, "pending_followups": 0},\n    }'''
new_block = '''        "applications": {"total": len(apps), "submitted": submitted, "by_status": {}, "by_portal": [], "funnel": []},\n        "outreach": {"drafts": 0, "approved_unsent": 0, "sent": 0, "replied": 0, "response_rate": 0, "positive": 0, "negative": 0, "action_required": 0, "send_failed": 0, "pending_followups": 0},\n        "top_jobs": sorted(apps, key=lambda x: (x.get("match_score") is not None, x.get("match_score") or -1), reverse=True)[:6],\n        "recent_applications": apps[:8],\n        "needs_attention": [a for a in apps if a.get("status") in {"error", "unknown_question", "ready_to_submit", "no_questions", "external_error"}][:12],\n    }'''
if old_block not in s:
    raise SystemExit('dashboard block anchor missing')
s = s.replace(old_block, new_block, 1)

# Applications endpoint optional limit/offset to prevent huge payloads from pages.
old = '''@app.get("/api/applications")\ndef applications(status: Optional[str] = None):\n    rows = _all_applications()\n    return [r for r in rows if not status or r.get("status") == status]\n'''
new = '''@app.get("/api/applications")\ndef applications(status: Optional[str] = None, limit: int = 200, offset: int = 0):\n    rows = _all_applications()\n    rows = [r for r in rows if not status or r.get("status") == status]\n    return rows[max(0, offset):max(0, offset) + max(1, min(limit, 500))]\n'''
if old not in s:
    raise SystemExit('applications endpoint anchor missing')
s = s.replace(old, new, 1)

# Add limit to needs-attention.
old = '''@app.get("/api/dashboard/needs-attention")\ndef needs_attention():\n    return [a for a in _all_applications() if a.get("status") in {"error", "unknown_question", "ready_to_submit", "no_questions", "external_error"}][:50]\n'''
new = '''@app.get("/api/dashboard/needs-attention")\ndef needs_attention(limit: int = 50):\n    return [a for a in _all_applications() if a.get("status") in {"error", "unknown_question", "ready_to_submit", "no_questions", "external_error"}][:max(1, min(limit, 100))]\n'''
if old not in s:
    raise SystemExit('attention endpoint anchor missing')
s = s.replace(old, new, 1)

p.write_text(s, encoding='utf-8')

# ---------------- frontend usePolling ----------------
p = root/'webapp/frontend/src/hooks/usePolling.ts'
s = p.read_text(encoding='utf-8')
new_hook = '''import { useEffect, useRef, useState, useCallback } from "react";\nimport { ApiError } from "../api/client";\n\n/** Lightweight polling with single-flight requests and tab visibility pausing.\n * This prevents overlapping REST calls from piling up when the backend is busy.\n */\nexport function usePolling<T>(fn: () => Promise<T>, intervalMs = 15000, deps: unknown[] = []) {\n  const [data, setData] = useState<T | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [loading, setLoading] = useState(true);\n  const fnRef = useRef(fn);\n  const inFlight = useRef(false);\n  const mounted = useRef(true);\n  fnRef.current = fn;\n\n  const refresh = useCallback(async () => {\n    if (!mounted.current || inFlight.current) return;\n    if (typeof document !== "undefined" && document.visibilityState === "hidden") return;\n    inFlight.current = true;\n    try {\n      const result = await fnRef.current();\n      if (mounted.current) {\n        setData(result);\n        setError(null);\n      }\n    } catch (e) {\n      if (mounted.current) setError(e instanceof ApiError ? e.message : String(e));\n    } finally {\n      inFlight.current = false;\n      if (mounted.current) setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    mounted.current = true;\n    setLoading(true);\n    void refresh();\n\n    const id = window.setInterval(refresh, Math.max(1000, intervalMs));\n    const onVisible = () => {\n      if (document.visibilityState === "visible") void refresh();\n    };\n    document.addEventListener("visibilitychange", onVisible);\n    return () => {\n      mounted.current = false;\n      window.clearInterval(id);\n      document.removeEventListener("visibilitychange", onVisible);\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, deps);\n\n  return { data, error, loading, refresh };\n}\n'''
p.write_text(new_hook, encoding='utf-8')

# ---------------- frontend api type/endpoints ----------------
p = root/'webapp/frontend/src/api/client.ts'
s = p.read_text(encoding='utf-8')
s = s.replace('''  outreach: { drafts: number; approved_unsent: number; sent: number; replied: number;\n    response_rate: number; positive: number; negative: number; action_required: number;\n    send_failed: number; pending_followups: number };\n}''', '''  outreach: { drafts: number; approved_unsent: number; sent: number; replied: number;\n    response_rate: number; positive: number; negative: number; action_required: number;\n    send_failed: number; pending_followups: number };\n  top_jobs?: Job[];\n  recent_applications?: Application[];\n  needs_attention?: Application[];\n}''', 1)
# jobs params
s = s.replace('''  jobs: (params: { portal?: string; eligible?: boolean; q?: string } = {}) => {\n    const qs = new URLSearchParams();\n    if (params.portal) qs.set("portal", params.portal);\n    if (params.eligible !== undefined) qs.set("eligible", String(params.eligible));\n    if (params.q) qs.set("q", params.q);\n    return get<Job[]>(`/api/jobs?${qs.toString()}`);\n  },''', '''  jobs: (params: { portal?: string; eligible?: boolean; q?: string; limit?: number; offset?: number } = {}) => {\n    const qs = new URLSearchParams();\n    if (params.portal) qs.set("portal", params.portal);\n    if (params.eligible !== undefined) qs.set("eligible", String(params.eligible));\n    if (params.q) qs.set("q", params.q);\n    if (params.limit !== undefined) qs.set("limit", String(params.limit));\n    if (params.offset !== undefined) qs.set("offset", String(params.offset));\n    return get<Job[]>(`/api/jobs?${qs.toString()}`);\n  },''', 1)
s = s.replace('''  applications: (status?: string) => get<Application[]>(`/api/applications${status ? `?status=${status}` : ""}`),''', '''  applications: (status?: string, limit = 200, offset = 0) => {\n    const qs = new URLSearchParams();\n    if (status) qs.set("status", status);\n    qs.set("limit", String(limit));\n    qs.set("offset", String(offset));\n    return get<Application[]>(`/api/applications?${qs.toString()}`);\n  },''', 1)
p.write_text(s, encoding='utf-8')

# ---------------- Dashboard reduce initial heavy calls ----------------
p = root/'webapp/frontend/src/pages/Dashboard.tsx'
s = p.read_text(encoding='utf-8')
s = s.replace('''  const { data, error, loading } = usePolling(() => api.dashboard(), 5000);\n  const { data: attention } = usePolling(() => api.needsAttention(), 8000);\n  const { data: jobs } = usePolling(() => api.jobs(), 15000);\n  const { data: apps } = usePolling(() => api.applications(), 8000);\n  const { data: cfg } = usePolling(() => api.config(), 15000);\n  const { data: run } = usePolling(() => api.automationStatus(), 4000);\n\n  const derived = useMemo(() => {\n    const list = apps || [];\n''', '''  const { data, error, loading } = usePolling(() => api.dashboard(), 20000);\n  const { data: cfg } = usePolling(() => api.config(), 60000);\n  const { data: run } = usePolling(() => api.automationStatus(), 8000);\n\n  const apps = data?.recent_applications ?? [];\n  const jobs = data?.top_jobs ?? [];\n  const attention = data?.needs_attention ?? [];\n\n  const derived = useMemo(() => {\n    const list = apps;\n''', 1)
s = s.replace('''    [jobs],\n  );''', '''    [jobs],\n  );''', 1)
p.write_text(s, encoding='utf-8')

# ---------------- Slow down expensive page polls ----------------
replacements = {
    'webapp/frontend/src/pages/Jobs.tsx': [('usePolling(\n    () => api.jobs({ portal: portal || undefined, eligible: eligibleOnly ? true : undefined, q: q || undefined }), 5000)', 'usePolling(\n    () => api.jobs({ portal: portal || undefined, eligible: eligibleOnly ? true : undefined, q: q || undefined, limit: 100 }), 20000)')],
    'webapp/frontend/src/pages/Tracker.tsx': [('usePolling(() => api.applications(), 6000)', 'usePolling(() => api.applications(undefined, 200), 12000)')],
    'webapp/frontend/src/pages/Approvals.tsx': [('usePolling(() => api.approvals(), 4000)', 'usePolling(() => api.approvals(), 12000)')],
    'webapp/frontend/src/pages/Recruiters.tsx': [('usePolling(() => api.recruiters(), 8000)', 'usePolling(() => api.recruiters(), 20000)')],
    'webapp/frontend/src/pages/Followups.tsx': [('usePolling(() => api.outreachList("sent"), 8000)', 'usePolling(() => api.outreachList("sent"), 20000)')],
    'webapp/frontend/src/pages/CustomQA.tsx': [('usePolling(() => api.qaList(), 5000)', 'usePolling(() => api.qaList(), 20000)')],
    'webapp/frontend/src/pages/Settings.tsx': [('usePolling(() => api.config(), 15000)', 'usePolling(() => api.config(), 60000)'), ('usePolling(() => api.status(), 10000)', 'usePolling(() => api.status(), 30000)')],
    'webapp/frontend/src/pages/ResumeTailoring.tsx': [('usePolling(() => api.jobs(), 8000)', 'usePolling(() => api.jobs({ limit: 100 }), 20000)'), ('usePolling(() => api.masterResume(), 60000)', 'usePolling(() => api.masterResume(), 300000)'), ('usePolling(() => api.resumeContentBank(), 60000)', 'usePolling(() => api.resumeContentBank(), 300000)')],
    'webapp/frontend/src/components/Layout.tsx': [('usePolling(() => api.status(), 8000)', 'usePolling(() => api.status(), 30000)'), ('usePolling(() => api.cdpStatus(), 6000)', 'usePolling(() => api.cdpStatus(), 12000)'), ('usePolling(() => api.automationStatus(), 3000)', 'usePolling(() => api.automationStatus(), 8000)'), ('usePolling(() => api.config(), 15000)', 'usePolling(() => api.config(), 60000)')],
    'webapp/frontend/src/pages/JobSearch.tsx': [('usePolling(() => api.cdpStatus(), 6000)', 'usePolling(() => api.cdpStatus(), 10000)'), ('usePolling(() => api.automationStatus(), 3000)', 'usePolling(() => api.automationStatus(), 4000)')],
}
for rel, reps in replacements.items():
    p = root/rel
    s = p.read_text(encoding='utf-8')
    for a,b in reps:
        if a in s:
            s = s.replace(a,b,1)
    p.write_text(s, encoding='utf-8')

# Fix Jobs exact replacement if formatting differed
p = root/'webapp/frontend/src/pages/Jobs.tsx'
s = p.read_text(encoding='utf-8')
s = s.replace('''  const { data, error, loading, refresh } = usePolling(\n    () => api.jobs({ portal: portal || undefined, eligible: eligibleOnly ? true : undefined, q: q || undefined }), 5_000);''', '''  const { data, error, loading, refresh } = usePolling(\n    () => api.jobs({ portal: portal || undefined, eligible: eligibleOnly ? true : undefined, q: q || undefined, limit: 100 }), 20_000);''')
p.write_text(s, encoding='utf-8')

# Add a lightweight startup performance note.
(root/'webapp/frontend/PERFORMANCE_FIX.md').write_text('''# Performance fix\n\nThe UI previously polled several expensive REST endpoints every 3-8 seconds, including endpoints that scan all platform SQLite databases and resume metadata.\n\nChanges:\n- Single-flight/visibility-aware polling so requests cannot overlap.\n- Dashboard now uses one aggregated `/api/dashboard` snapshot for top jobs, recent applications, and needs-attention data.\n- Dashboard poll reduced to 20s; config 60s; automation 8s.\n- Jobs/Applications/Tracker/Recruiters/Follow-ups/Approvals/QA polling slowed to practical intervals.\n- Backend caches the combined application snapshot briefly and builds resume availability once per snapshot instead of scanning resume records for every row.\n- `/api/applications` now supports `limit`/`offset`.\n''', encoding='utf-8')

print('Performance patch applied')
